# Clean-CPS re-entry addrs: coroutine continuation / branch-target PCs that
# are NOT function entries (no fnmap row) but must route to a clean body so a
# yielded CD/IRQ coroutine resumes inside clean C. Multiple addrs may name the
# same symbol; clean_try_dispatch hands the fn cpu->pc == the dispatched addr
# so the body's pc-switch picks the right continuation block.
#
# cd_irq_init_seq (guest 0x8019A87C) — CD IRQ/init sequencing coroutine.
# Entry + its 7 CPS continuation/branch-target blocks all re-enter the same
# clean body; 0x8019A8DC is the NEXT function (stays generated).
8019a87c cd_irq_init_seq
8019a884 cd_irq_init_seq
8019a88c cd_irq_init_seq
8019a8a4 cd_irq_init_seq
8019a8b0 cd_irq_init_seq
8019a8c0 cd_irq_init_seq
8019a8d0 cd_irq_init_seq
8019a8d8 cd_irq_init_seq

# cd_response_pump (guest 0x801979F8) — CD deferred-work pump coroutine.
# Entry + 11 CPS continuation/branch-target blocks; drives clean
# cd_response_process. INTC handler[2] @0x801bcd1c.
801979f8 cd_response_pump
80197a2c cd_response_pump
80197a34 cd_response_pump
80197a40 cd_response_pump
80197a48 cd_response_pump
80197a5c cd_response_pump
80197a6c cd_response_pump
80197a70 cd_response_pump
80197a78 cd_response_pump
80197a8c cd_response_pump
80197a9c cd_response_pump
80197aa4 cd_response_pump
